// Calculate date ranges
const now = new Date();

// Yesterday range
const yesterday = new Date(now);
yesterday.setDate(yesterday.getDate() - 1);
yesterday.setHours(0, 0, 0, 0);

const yesterdayEnd = new Date(yesterday);
yesterdayEnd.setHours(23, 59, 59, 999);

// Stripe payouts typically arrive T+2, so check 3 days ago
const threeDaysAgo = new Date(now);
threeDaysAgo.setDate(threeDaysAgo.getDate() - 3);
threeDaysAgo.setHours(0, 0, 0, 0);

// Unix timestamps for Stripe API
const threeDaysAgoUnix = Math.floor(threeDaysAgo.getTime() / 1000);
const yesterdayEndUnix = Math.floor(yesterdayEnd.getTime() / 1000);

return [{
  json: {
    yesterday: yesterday.toISOString().split('T')[0],
    yesterdayEnd: yesterdayEnd.toISOString().split('T')[0],
    threeDaysAgo: threeDaysAgo.toISOString().split('T')[0],
    threeDaysAgoUnix,
    yesterdayEndUnix
  }
}];

// Merge payout and income data
const stripeData = $('HTTP - Get Stripe Payouts').first()?.json || { data: [] };
const incomeItems = $('Sheets - Get Incomes').all() || [];

const payouts = stripeData.data || [];
const incomes = incomeItems.map(item => item.json);

// Filter incomes to recent date range
const dateRange = $('Code - Calculate Date Range').first().json;
const threeDaysAgo = new Date(dateRange.threeDaysAgo);
const yesterdayEnd = new Date(dateRange.yesterdayEnd);

const recentIncomes = incomes.filter(income => {
  const incomeDate = new Date(income.Date);
  return incomeDate >= threeDaysAgo && incomeDate <= yesterdayEnd;
});

return [{
  json: {
    payouts,
    incomes: recentIncomes,
    payoutCount: payouts.length,
    incomeCount: recentIncomes.length
  }
}];

// Match Stripe payouts to recorded income (deposits)
const data = $input.first().json;
const stripePayouts = data.payouts;
const recordedIncomes = [...data.incomes];

const reconciliation = {
  matched: [],
  unmatchedPayouts: [],
  unmatchedIncomes: [...recordedIncomes]
};

const matchTransaction = (payout, incomes) => {
  const payoutAmount = payout.amount / 100; // Convert cents
  const payoutDate = new Date(payout.arrival_date * 1000);

  // Try exact match first
  let match = incomes.find(income => {
    const incomeAmount = parseFloat(income['Net Amount']) || 0;
    const incomeDateStr = income.Date;
    if (!incomeDateStr) return false;

    const incomeDate = new Date(incomeDateStr);
    const dateDiff = Math.abs(incomeDate - payoutDate);

    // Exact amount, within ±2 days
    return Math.abs(incomeAmount - payoutAmount) < 0.01 &&
           dateDiff <= 2 * 24 * 60 * 60 * 1000;
  });

  // If no exact match, try fuzzy
  if (!match) {
    match = incomes.find(income => {
      const incomeAmount = parseFloat(income['Net Amount']) || 0;
      const incomeDateStr = income.Date;
      if (!incomeDateStr) return false;

      const incomeDate = new Date(incomeDateStr);
      const dateDiff = Math.abs(incomeDate - payoutDate);

      // Within $10, within ±3 days
      return Math.abs(incomeAmount - payoutAmount) <= 10 &&
             dateDiff <= 3 * 24 * 60 * 60 * 1000;
    });
  }

  return match;
};

const calculateConfidence = (payout, income) => {
  const payoutAmount = payout.amount / 100;
  const incomeAmount = parseFloat(income['Net Amount']) || 0;
  const payoutDate = new Date(payout.arrival_date * 1000);
  const incomeDate = new Date(income.Date);

  let confidence = 0;

  // Amount matching
  const amountDiff = Math.abs(payoutAmount - incomeAmount);
  if (amountDiff < 0.01) confidence += 50;
  else if (amountDiff <= 5) confidence += 40;
  else if (amountDiff <= 10) confidence += 30;

  // Date matching
  const dateDiff = Math.abs(payoutDate - incomeDate) / (24 * 60 * 60 * 1000);
  if (dateDiff < 1) confidence += 50;
  else if (dateDiff <= 2) confidence += 40;
  else if (dateDiff <= 3) confidence += 30;

  return Math.round(confidence);
};

// Process each payout
for (const payout of stripePayouts) {
  const match = matchTransaction(payout, reconciliation.unmatchedIncomes);

  if (match) {
    const confidence = calculateConfidence(payout, match);
    reconciliation.matched.push({
      payout: {
        id: payout.id,
        amount: payout.amount / 100,
        arrivalDate: new Date(payout.arrival_date * 1000).toISOString().split('T')[0],
        status: payout.status
      },
      income: {
        customer: match.Customer || 'Unknown',
        amount: parseFloat(match['Net Amount']) || 0,
        date: match.Date,
        rowNumber: match.row_number
      },
      confidence
    });

    // Remove from unmatched
    const index = reconciliation.unmatchedIncomes.findIndex(i => i.row_number === match.row_number);
    if (index > -1) {
      reconciliation.unmatchedIncomes.splice(index, 1);
    }
  } else {
    const payoutAge = (Date.now() - payout.arrival_date * 1000) / (24 * 60 * 60 * 1000);
    reconciliation.unmatchedPayouts.push({
      id: payout.id,
      amount: payout.amount / 100,
      arrivalDate: new Date(payout.arrival_date * 1000).toISOString().split('T')[0],
      status: payout.status,
      daysOld: Math.round(payoutAge),
      isOld: payoutAge > 3
    });
  }
}

// Calculate totals
const matchedTotal = reconciliation.matched.reduce((sum, m) => sum + m.payout.amount, 0);
const unmatchedPayoutTotal = reconciliation.unmatchedPayouts.reduce((sum, p) => sum + p.amount, 0);
const unmatchedIncomeTotal = reconciliation.unmatchedIncomes.reduce((sum, i) => 
  sum + (parseFloat(i['Net Amount']) || 0), 0
);

return [{
  json: {
    reconciliation,
    summary: {
      matchedCount: reconciliation.matched.length,
      matchedTotal,
      unmatchedPayoutCount: reconciliation.unmatchedPayouts.length,
      unmatchedPayoutTotal,
      unmatchedIncomeCount: reconciliation.unmatchedIncomes.length,
      unmatchedIncomeTotal,
      hasOldUnmatched: reconciliation.unmatchedPayouts.some(p => p.isOld)
    }
  }
}];

// Prepare reconciliation records for Sheets
const data = $input.first().json;
const matched = data.reconciliation.matched;
const today = new Date().toISOString().split('T')[0];

// Return items to log in Reconciliation sheet
return matched.map(m => ({
  json: {
    Date: today,
    'Stripe Payout ID': m.payout.id,
    'Payout Amount': m.payout.amount,
    'Payout Date': m.payout.arrivalDate,
    'Matched Income Row': m.income.rowNumber,
    'Income Amount': m.income.amount,
    'Confidence': m.confidence,
    'Status': 'Matched',
    'Notes': `Auto-reconciled. Confidence: ${m.confidence}%`
  }
}));

// Prepare unmatched payout records for Sheets
const data = $('Code - Reconcile').first().json;
const unmatched = data.reconciliation.unmatchedPayouts;
const today = new Date().toISOString().split('T')[0];

return unmatched.map(p => ({
  json: {
    Date: today,
    'Stripe Payout ID': p.id,
    'Payout Amount': p.amount,
    'Payout Date': p.arrivalDate,
    'Matched Income Row': '',
    'Income Amount': '',
    'Confidence': 0,
    'Status': 'Unmatched',
    'Notes': `Payout not yet matched to Relay deposit. Days old: ${p.daysOld}. Check manually if not received within 5 business days.`
  }
}));

// Format daily summary report
const data = $('Code - Reconcile').first().json;
const { summary, reconciliation } = data;
const sheetsUrl = `https://docs.google.com/spreadsheets/d/${$env.GOOGLE_SHEETS_FINANCE_ID}`;

let message = `:moneybag: *Daily Reconciliation Report*\n\n`;

message += `:white_check_mark: *Matched:* ${summary.matchedCount} transfers ($${summary.matchedTotal.toFixed(2)})\n`;
message += `:warning: *Unmatched Stripe Payouts:* ${summary.unmatchedPayoutCount} ($${summary.unmatchedPayoutTotal.toFixed(2)})\n`;
message += `:warning: *Unmatched Incomes:* ${summary.unmatchedIncomeCount} ($${summary.unmatchedIncomeTotal.toFixed(2)})\n\n`;

if (summary.hasOldUnmatched) {
  message += `:rotating_light: *Alert:* Some payouts are >3 days old and still unmatched. Manual review required.\n\n`;

  reconciliation.unmatchedPayouts.filter(p => p.isOld).forEach(p => {
    message += `• $${p.amount.toFixed(2)} - Payout ${p.id} (${p.daysOld} days old)\n`;
  });
  message += '\n';
}

message += `<${sheetsUrl}|View Reconciliation in Google Sheets>`;

return [{ json: { message, summary } }];

// Send urgent alert for old unmatched payouts
const data = $('Code - Reconcile').first().json;
const oldUnmatched = data.reconciliation.unmatchedPayouts.filter(p => p.isOld);
const total = oldUnmatched.reduce((sum, p) => sum + p.amount, 0);

let alertMessage = `:rotating_light: *URGENT: Unmatched Payouts >3 Days Old*\n\n`;
alertMessage += `*${oldUnmatched.length} payouts totaling $${total.toFixed(2)} have not been matched to Relay deposits.*\n\n`;

oldUnmatched.forEach(p => {
  alertMessage += `• $${p.amount.toFixed(2)} - ${p.id} (${p.daysOld} days old, expected ${p.arrivalDate})\n`;
});

alertMessage += `\n*Action Required:* Check Relay account manually for these deposits.`;

return [{ json: { alertMessage, count: oldUnmatched.length, total } }];
